CREATE TABLE IF NOT EXISTS kanban_card (
  id          INTEGER PRIMARY KEY,
  lane_id     TEXT NOT NULL,
  title       TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  sort_key    REAL NOT NULL,
  created     TEXT NOT NULL DEFAULT (datetime('now')),
  updated     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS kanban_card_lane_order
  ON kanban_card(lane_id, sort_key, id);
CREATE TABLE IF NOT EXISTS kanban_meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
INSERT OR IGNORE INTO kanban_card (id, lane_id, title, description, sort_key)
SELECT 1, 'backlog', 'Collect launch feedback', 'Pull the notes from the beta group into one place.', 1024
 WHERE NOT EXISTS (SELECT 1 FROM kanban_meta WHERE key = 'starter-seeded');
